// SystemReplace.cpp : Defines the entry point for the DLL application.//#include "stdafx.h"#include "SystemReplace.h"#ifdef LINUX#include "LogFile.h"#endif // LINUX#ifdef _MANAGED#pragma managed(push, off)#endifvoid InitBreak();void InitRand( int n );BOOL APIENTRY DllMain( HMODULE hModule,                       DWORD  ul_reason_for_call,                       LPVOID lpReserved					 ){	switch (ul_reason_for_call)	{	case DLL_PROCESS_ATTACH:	{#ifdef LINUX		CLogFile::Initialize ("SystemRelpDll");		CLogFile::Log ("SystemRelpDll started");#endif // LINUX		InitBreak();		InitRand( 1 );	}    break;	case DLL_THREAD_ATTACH:	case DLL_THREAD_DETACH:	case DLL_PROCESS_DETACH:		break;	}    return TRUE;}#ifdef _MANAGED#pragma managed(pop)#endif/*// This is an example of an exported variableSYSTEMREPLACE_API int nSystemReplace=0;// This is an example of an exported function.SYSTEMREPLACE_API int fnSystemReplace(void){	return 42;}// This is the constructor of a class that has been exported.// see SystemReplace.h for the class definitionCSystemReplace::CSystemReplace(){	return;}*/